mapper.select:
SELECT id, aggregate_id AS shipmentId, attempts FROM outbox_events
WHERE event_type = 'SHIPMENT_AUTO_CONFIRM' AND status = 'PENDING'
  AND next_attempt_at <= #{now}
  AND (claim_until IS NULL OR claim_until <= #{now})
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE outbox_events SET claim_token = #{token}, claim_until = #{until}
WHERE id = #{eventId} AND event_type = 'SHIPMENT_AUTO_CONFIRM'
  AND status = 'PENDING' AND next_attempt_at <= #{now}
  AND (claim_until IS NULL OR claim_until <= #{now})

UPDATE outbox_events SET status = 'PUBLISHED', published_at = #{now}, attempts = attempts + 1,
                         claim_token = NULL, claim_until = NULL
WHERE id = #{eventId} AND status = 'PENDING' AND claim_token = #{token}

UPDATE outbox_events SET attempts = attempts + 1, next_attempt_at = #{nextAttemptAt},
                         claim_token = NULL, claim_until = NULL
WHERE id = #{eventId} AND status = 'PENDING' AND claim_token = #{token}

UPDATE outbox_events SET status = 'DEAD', attempts = attempts + 1,
                         claim_token = NULL, claim_until = NULL
WHERE id = #{eventId} AND status = 'PENDING' AND claim_token = #{token}

UPDATE outbox_events SET claim_token = #{token}, claim_until = #{until}
WHERE id = #{eventId} AND event_type IN
  ('SEARCH_PRODUCT_REFRESH', 'SEARCH_SHOP_REFRESH', 'SEARCH_BRAND_REFRESH', 'SEARCH_CATEGORY_REFRESH')
  AND status = 'PENDING' AND next_attempt_at <= #{now}
  AND (claim_until IS NULL OR claim_until <= #{now})
